select to_char(date_trunc('month', a.dt_end), 'MM.YYYY') as month
        , ot.id_object_type_top
        , (select name from object_type where  id_object_type = ot.id_object_type_top) as name
        , count(*) as cnt
        , sum(a.applied_commission) as sum_commision
        , sum(a.applied_commission)/count(*) as average_commision
from auction a, object oo, object_type ot
where a.id_object = oo.id_object
    and oo.id_object_type = ot.id_object_type
    and status in ('SUCCESS', 'BUYNOW')
    and is_deleted = 'N'
    and dt_end >= to_date('01.01.2023','DD.MM.YYYY')
    and dt_end < to_date('01.04.2023','DD.MM.YYYY')
group by
         date_trunc('month', a.dt_end)
        , ot.id_object_type_top
order by date_trunc('month', a.dt_end), id_object_type_top
;
