create function carl_prof.getProfList()
SELECT id_profile, prof_type, name, name2, is_default, status, id_user_owner, bal_sum, bal_res, is_vip, roles
from getproflistbyuserid(57475);
getProfDomainInfo
select up.id_user, p.id_profile
, carl_prof._get_prof_log_domain(p.id_profile) log_domain
, (p.parameters ? 'employer') promo
, p.id_individual is not null indiv
from
user_profile up, profile p
left join company c on (p.id_company = c.id_company)
left join individual i on (i.id_individual = p.id_individual)
where ( up.id_profile = p.id_profile )
-- and (3 is null or up.id_user = 3)
and up.id_user in (37485, 48552)
and up.is_deleted = 'N' and p.is_deleted = 'N'
and	(up.dt_expire is null or up.dt_expire >= current_timestamp)
order by p.status desc, name
;
